//! The GPU side of the pipeline: pipelines, per-frame upload, and pass recording.
//!
//! [`Renderer`] owns a headless [`Gpu`] (from `ludion-render-graph`, reused for adapter selection and
//! the blocking readback) plus every pipeline, the procedural mesh buffers, and the bitmap-font
//! atlas — all built once. [`Renderer::render`] takes a [`RenderScene`], uploads its per-frame
//! resources, and drives the frame graph: for each pass the graph resolves texture views and calls
//! back into [`FrameRecorder`], which records the actual draws. Determinism: the same scene on the
//! same adapter produces byte-identical pixels, across processes.

