// The CPU mirror of the WGSL uniform/storage structs and hoisted consts, generated by
// `ludion-shader-bindgen` (`shader_gen.rs`). These replace the former hand-written `*Raw` PODs —
// edit the WGSL and regenerate, never hand-edit the layouts. The module also carries the generated
// binding-index consts (`*_GROUP`/`*_BINDING`), BGL descriptors (`create_*_bgl`), and reflected
// vertex-input lists (`*_VS_MAIN_INPUTS`) the hand-written pipeline attribute literals are
// drift-tested against.
use crate::shader_gen;
use crate::shader_gen::{
    ATLAS_TEX_GROUP, BONE_PALETTE_BINDING, BloomThreshold, CAMERA_BINDING, CAMERA_GROUP,
    CLUSTER_LIGHTS_BINDING, CLUSTER_TABLE_BINDING, Camera, Composite, DownsampleParams,
    ENV_BINDING, ENV_GROUP, ENV_SAMP_BINDING, EnvParams, IRRADIANCE_TEX_BINDING,
    LIGHT_LIST_BINDING, LIGHTS_BINDING, LIGHTS_GROUP, MATERIAL_ALPHA_MASK, MATERIAL_BASE_COLOR,
    MATERIAL_DOUBLE_SIDED, MATERIAL_EMISSIVE, MATERIAL_GROUP, MATERIAL_METALLIC_ROUGHNESS,
    MATERIAL_NORMAL, MATERIAL_OCCLUSION, MeshMaterial, PROFILES_BINDING, PROFILES_GROUP,
    RECT_TEX_GROUP, ResolveParams, SHADOW_VIEW_BINDING, SHADOW_VIEW_GROUP, SKY_GROUP,
    SPRITE_TEX_GROUP, SRC_TEX_GROUP, SUN_GROUP, Sky, Sun, UI_GROUP, Ui, UpsampleParams,
    UpscaleParams,
};
