impl ShaderId {
    /// This shader's registry row.
    fn desc(self) -> &'static ShaderDesc {
        &SHADERS[self as usize]
    }

    /// Every reloadable renderer shader, in registry order (snippet-reload dependents, path lookup,
    /// the composition drift test).
    pub(crate) fn all() -> impl Iterator<Item = ShaderId> {
        SHADERS.iter().map(|desc| desc.id)
    }

    /// This shader's `.wgsl` file name.
    pub(crate) fn file_name(self) -> &'static str {
        self.desc().file_name
    }

    /// The shared snippets composed ahead of this shader's body, in declared order.
    pub(crate) fn snippets(self) -> &'static [Snippet] {
        self.desc().snippets
    }

    /// The compiled-in *body* source.
    fn body_source(self) -> &'static str {
        self.desc().body
    }

    /// The debug label for this shader's module, pipeline layout and pipeline: its file name without
    /// the extension.
    fn label(self) -> &'static str {
        self.file_name().trim_end_matches(".wgsl")
    }
}

/// A shared WGSL snippet composed ahead of the shaders that use it (Plan/shader-bindgen.md decision
/// 16), so a declaration lives in one place instead of copy-pasted across shaders. The mapping from a
/// shader to its snippets is [`ShaderId::snippets`]; a snippet edit hot-reloads every dependent
/// pipeline (`Renderer::reload_snippet`).
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub(crate) enum Snippet {
    /// `Camera` uniform struct + its `@group(0)` binding (mesh, sprite, particle, text, ground
    /// marker).
    Camera,
    /// The cluster grid's consts and `cluster_cell`, binding-free (`lights.wgsl`'s index, the
    /// reflections pass's probe masks).
    ClusterGrid,
    /// `ShadeProbe`, `probe_weight`, `probe_lookup`, `probe_ratio` and `probe_relit`, binding-free
    /// (reflections; the twins of `probe.rs`).
    Probes,
    /// The GI bake's ray set and geometry helpers (`GiBinParams`, `ray_direction`, `nonzero`,
    /// `cell_center`, `bin_cell_of`), binding-free (the bake and the injection compute shaders).
    GiRays,
    /// The clustered-forward light set: the grid consts, the `Light`/`LightHeader` structs, all four
    /// `@group(1)` bindings and the `cluster_slice` lookup (mesh, sprite, particle).
    Lights,
    /// The fullscreen-triangle `VsOut` + `vs_main` (blit, blur, threshold, composite).
    FullscreenVs,
    /// The `BAYER4` ordered dither tile (mesh's screen-door fade, the output dither, the SSAO
    /// rotation, the light-shaft march's step offset).
    Bayer,
    /// The participating medium's geometry — its optical depth and local density as functions of
    /// distance and world height (the composite's analytic haze, the light-shaft march).
    Medium,
    /// The `Environment`'s authored sky radiance as a function of direction (the sky background, the
    /// composite's sky-coupled ambient in-scatter, the IBL bake's cube and diffuse sky).
    SkyGradient,
    /// The GPU bone palette's `@group(0) @binding(1)` storage buffer and the `skin_matrix` blend
    /// function (mesh, prepass, shadow — Plan/skeletal-animation.md).
    Skin,
    /// The scene radiance ceiling `HDR_CEILING` and `hdr_safe`, which keeps a lit value below
    /// half-float overflow and reads a NaN as zero (mesh, and the bloom chain's threshold and
    /// pyramid).
    Hdr,
    /// `specular_cube_lod`, the specular cube's lod for a roughness (`specular_ibl.wgsl`, so the
    /// reflections pass; the twin of `lobe.rs::cube_lod`).
    Lobe,
    /// `visibility_smith` and the multi-scatter DFG compensation (`dfg_energy`, `dfg_specular`),
    /// binding-free (mesh, reflections, ssr_blend, and the `ibl.wgsl` compute).
    Dfg,
    /// `sky_specular`, the sky's specular IBL for a surface point, binding-free (reflections).
    SpecularIbl,
    /// `sh_l1` and `sky_visibility_at`, the one read of the sky-visibility probe volume,
    /// binding-free (mesh, reflections).
    GiProbe,
    /// The mesh lighting — groups 2–3 and `shade` (mesh).
    MeshShading,
    /// The per-draw material maps and flags — `@group(4)`, the cutout and back-face tests (mesh,
    /// prepass).
    MeshMaterial,
    /// The pyramid footprint rule — a child texel's source interval and the texels it touches,
    /// binding-free (the Hi-Z and SSR colour pyramids).
    Footprint,
    /// `ssr_confidence` and `ssr_source_pixel`, the SSR trace's shared pure functions, binding-free
    /// (the trace; the twin of `ssr_trace.rs::confidence`).
    Ssr,
    /// `linear_to_srgb` / `srgb_to_linear`, the transfer pair, binding-free (composite,
    /// ssr_debug, probe_debug).
    Srgb,
    /// `grain_offset` and `encoded_output`, the grain and ordered output dither applied in the encoded
    /// domain, binding-free (composite, smaa_blend, resolve, upscale).
    OutputEncode,
    /// The glyph-atlas `@group(1)` bindings, the shared `VsOut` and the coverage `fs_main` (text,
    /// ui_text).
    Glyph,
    /// `sd_rounded_box`, the disc-and-capsule footprint distance, binding-free (ground_marker,
    /// projector).
    RoundedBox,
    /// `ProjectorDecal`, the unit-cube vertex, the angle fade and the map gradient clamp,
    /// binding-free (projector, decal_lit).
    Decal,
    /// `shade_two_sided`, the light rule of a flat camera-facing billboard (sprite, and a lit
    /// particle's centre); needs the `Camera` and `Lights` snippets ahead of it.
    BillboardLight,
    /// `view_to_eye` and `view_from_eye`, which pick an orthographic camera's single view direction
    /// over the per-pixel vector to the eye, binding-free (mesh, decal_lit, sky, reflections,
    /// ssr_blend, ssr_trace).
    ViewRay,
    /// `transparent_layer`, the value a layer fragment writes into the `Rg16Float` transparent layer
    /// (sprite, particle, text); needs the `Camera` snippet ahead of it.
    TransparentLayer,
    /// `PI` and `TAU`, binding-free (mesh, decal_lit, the `ibl.wgsl`, `gi_bake.wgsl` and `gi_inject.wgsl`
    /// computes, ssao).
    Math,
    /// `CORNERS` and `QUAD_PAD`, the quad every billboard-like pass draws, binding-free
    /// (ground_marker, particle, sprite).
    Quad,
    /// `SOFT_FALLOFF`, the soft-edge gaussian exponent, binding-free (particle, projector).
    SoftFalloff,
    /// `world_from_depth`, a pixel's world position from its stored device depth and the pass's
    /// `inv_view_proj`, binding-free (ssao, projector, dof_coc).
    WorldFromDepth,
    /// `occluder_top`, the height of the nearest shadow caster over a world point in the overhead
    /// rain-occlusion map, binding-free (rain, mesh).
    RainOcclusion,
}

impl Snippet {
    /// Every snippet.
    pub(crate) const ALL: [Snippet; 32] = [
        Snippet::Camera,
        Snippet::ClusterGrid,
        Snippet::Probes,
        Snippet::Lights,
        Snippet::FullscreenVs,
        Snippet::Bayer,
        Snippet::Medium,
        Snippet::SkyGradient,
        Snippet::GiRays,
        Snippet::Skin,
        Snippet::Hdr,
        Snippet::Lobe,
        Snippet::Dfg,
        Snippet::SpecularIbl,
        Snippet::GiProbe,
        Snippet::MeshShading,
        Snippet::MeshMaterial,
        Snippet::Footprint,
        Snippet::Ssr,
        Snippet::Srgb,
        Snippet::OutputEncode,
        Snippet::Glyph,
        Snippet::RoundedBox,
        Snippet::Decal,
        Snippet::BillboardLight,
        Snippet::ViewRay,
        Snippet::TransparentLayer,
        Snippet::Quad,
        Snippet::Math,
        Snippet::SoftFalloff,
        Snippet::WorldFromDepth,
        Snippet::RainOcclusion,
    ];

    /// The snippet's file name under `shaders/snippets/`; its reload key is `snippets/<file name>`.
    pub(crate) fn file_name(self) -> &'static str {
        match self {
            Snippet::Camera => "camera.wgsl",
            Snippet::ClusterGrid => "cluster_grid.wgsl",
            Snippet::Probes => "probes.wgsl",
            Snippet::Lights => "lights.wgsl",
            Snippet::FullscreenVs => "fullscreen_vs.wgsl",
            Snippet::Bayer => "bayer.wgsl",
            Snippet::Medium => "medium.wgsl",
            Snippet::SkyGradient => "sky_gradient.wgsl",
            Snippet::GiRays => "gi_rays.wgsl",
            Snippet::Skin => "skin.wgsl",
            Snippet::Hdr => "hdr.wgsl",
            Snippet::Lobe => "lobe.wgsl",
            Snippet::Dfg => "dfg.wgsl",
            Snippet::SpecularIbl => "specular_ibl.wgsl",
            Snippet::GiProbe => "gi_probe.wgsl",
            Snippet::MeshShading => "mesh_shading.wgsl",
            Snippet::MeshMaterial => "mesh_material.wgsl",
            Snippet::Footprint => "footprint.wgsl",
            Snippet::Ssr => "ssr.wgsl",
            Snippet::Srgb => "srgb.wgsl",
            Snippet::OutputEncode => "output_encode.wgsl",
            Snippet::Glyph => "glyph.wgsl",
            Snippet::RoundedBox => "rounded_box.wgsl",
            Snippet::Decal => "decal.wgsl",
            Snippet::BillboardLight => "billboard_light.wgsl",
            Snippet::ViewRay => "view_ray.wgsl",
            Snippet::TransparentLayer => "transparent_layer.wgsl",
            Snippet::Quad => "quad.wgsl",
            Snippet::Math => "math.wgsl",
            Snippet::SoftFalloff => "soft_falloff.wgsl",
            Snippet::WorldFromDepth => "world_from_depth.wgsl",
            Snippet::RainOcclusion => "rain_occlusion.wgsl",
        }
    }

    /// The compiled-in snippet source (`include_str!`).
    pub(crate) fn builtin_source(self) -> &'static str {
        match self {
            Snippet::Camera => include_str!("shaders/snippets/camera.wgsl"),
            Snippet::ClusterGrid => include_str!("shaders/snippets/cluster_grid.wgsl"),
            Snippet::Probes => include_str!("shaders/snippets/probes.wgsl"),
            Snippet::Lights => include_str!("shaders/snippets/lights.wgsl"),
            Snippet::FullscreenVs => include_str!("shaders/snippets/fullscreen_vs.wgsl"),
            Snippet::Bayer => include_str!("shaders/snippets/bayer.wgsl"),
            Snippet::Medium => include_str!("shaders/snippets/medium.wgsl"),
            Snippet::SkyGradient => include_str!("shaders/snippets/sky_gradient.wgsl"),
            Snippet::GiRays => include_str!("shaders/snippets/gi_rays.wgsl"),
            Snippet::Skin => include_str!("shaders/snippets/skin.wgsl"),
            Snippet::Hdr => include_str!("shaders/snippets/hdr.wgsl"),
            Snippet::Lobe => include_str!("shaders/snippets/lobe.wgsl"),
            Snippet::Dfg => include_str!("shaders/snippets/dfg.wgsl"),
            Snippet::SpecularIbl => include_str!("shaders/snippets/specular_ibl.wgsl"),
            Snippet::GiProbe => include_str!("shaders/snippets/gi_probe.wgsl"),
            Snippet::MeshShading => include_str!("shaders/snippets/mesh_shading.wgsl"),
            Snippet::MeshMaterial => include_str!("shaders/snippets/mesh_material.wgsl"),
            Snippet::Footprint => include_str!("shaders/snippets/footprint.wgsl"),
            Snippet::Ssr => include_str!("shaders/snippets/ssr.wgsl"),
            Snippet::Srgb => include_str!("shaders/snippets/srgb.wgsl"),
            Snippet::OutputEncode => include_str!("shaders/snippets/output_encode.wgsl"),
            Snippet::Glyph => include_str!("shaders/snippets/glyph.wgsl"),
            Snippet::RoundedBox => include_str!("shaders/snippets/rounded_box.wgsl"),
            Snippet::Decal => include_str!("shaders/snippets/decal.wgsl"),
            Snippet::BillboardLight => include_str!("shaders/snippets/billboard_light.wgsl"),
            Snippet::ViewRay => include_str!("shaders/snippets/view_ray.wgsl"),
            Snippet::TransparentLayer => {
                include_str!("shaders/snippets/transparent_layer.wgsl")
            }
            Snippet::Quad => include_str!("shaders/snippets/quad.wgsl"),
            Snippet::Math => include_str!("shaders/snippets/math.wgsl"),
            Snippet::SoftFalloff => include_str!("shaders/snippets/soft_falloff.wgsl"),
            Snippet::WorldFromDepth => include_str!("shaders/snippets/world_from_depth.wgsl"),
            Snippet::RainOcclusion => include_str!("shaders/snippets/rain_occlusion.wgsl"),
        }
    }
}

/// The compiled-in composed source for `id`'s pipeline — its shared snippets (builtins) then its body,
/// joined by `\n`. The no-overlay case of [`Renderer::compose`], used to build every pipeline in
/// [`Renderer::new`] before any reload.
fn builtin_composed(id: ShaderId) -> String {
    compose_builtin(id.snippets(), id.body_source())
}

/// The one join of a shader's composition: the snippets' compiled-in sources then `body`, joined by
/// `\n`. Render and compute shaders both compose through it.
pub(crate) fn compose_builtin(snippets: &[Snippet], body: &str) -> String {
    let mut parts: Vec<&str> = snippets.iter().map(|s| s.builtin_source()).collect();
    parts.push(body);
    parts.join("\n")
}

/// The default shader directory: where `ludion dev`'s WGSL fast path watches, and the only place a
/// reload path may name a file unless the host chose another (`Engine::enable_shader_reload_from`).
pub const SHADER_SOURCE_DIR: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/src/shaders");

/// One bind group layout per unified WGSL name-set (Plan/shader-bindgen.md decision 13) — *not* one
/// per shader: `mesh` binds five of these and `ui_rect` two. The discriminant indexes [`LAYOUTS`] and
/// [`Layouts`], so a variant and its row must stay in the same order (asserted in [`Layouts::new`]).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum LayoutId {
    Camera,
    /// Mesh and prepass's own group 0: `camera` plus the bone palette — distinct from [`Camera`](LayoutId::Camera)
    /// (which ground-marker, sprite, particle and text keep unchanged) because only mesh and prepass
    /// skin vertices.
    CameraSkin,
    Lights,
    Sun,
    Env,
    MeshMaterial,
    Sky,
    ShadowView,
    SpriteTex,
    Atlas,
    Rect,
    Src,
    BloomDown,
    BloomUp,
    LensDown,
    LensUp,
    Threshold,
    Composite,
    Resolve,
    Upscale,
    Ssao,
    Shafts,
    MediumScatter,
    MediumScatterBlur,
    DofCoc,
    Dof,
    BoxBlur,
    Ui,
    DebugLine,
    Reflections,
    SsrBlend,
    HizSeed,
    HizReduce,
    SsrColor,
    SsrTrace,
    SsrDebug,
    ProbeFace,
    ProbeDebug,
    Projector,
    LocalShadowDebug,
    ExposureMeterDebug,
    /// The projector's group 1: the decal batch's base-colour map and its sampler.
    ProjectorMap,
    /// The receiver-id pass's group 1: `scene_depth`, the draw's mesh indices and its base offset.
    DecalReceiver,
    /// The lit decal pass's group 4: the depth, the receiver surface and ids, the decals, and a
    /// batch's three maps with their samplers.
    DecalLit,
    /// The SMAA edge pass: the composite, its sampler and the render-extent metrics.
    SmaaEdges,
    /// The SMAA weight pass: the edges and the two lookup tables.
    SmaaWeights,
    /// The SMAA blend pass: the composite and the weights.
    SmaaBlend,
    /// The medium march's group 1: the four baked GI volumes.
    MediumScatterGi,
    /// The ground-marker pass's group 1: the clipped markers' visibility profiles.
    GroundMarkerProfiles,
    /// The rain pass's group 2: the lattice parameters.
    Rain,
    /// The mesh pipelines' group 3: [`Env`](LayoutId::Env) plus the rain-occlusion map the wetness reads.
    /// The lit decal pass keeps `Env`: it already fills the fragment stage's sampled-texture limit.
    EnvWet,
    /// The screen-effect pass: the layer it filters, a sampler and the effect's parameters.
    ScreenEffect,
}

/// The number of bind group layouts — the length of [`LAYOUTS`] and of [`Layouts`].
const LAYOUT_COUNT: usize = 52;

/// One row of the layout registry: a [`LayoutId`] and the generated constructor that builds it.
struct LayoutDesc {
    /// The layout this row describes; must equal its index in [`LAYOUTS`].
    id: LayoutId,
    create: fn(&wgpu::Device) -> wgpu::BindGroupLayout,
}

