/// `LessEqual` with no write is the sprite pass's depth policy: a particle is occluded by the
/// geometry in front of it and occludes nothing itself, so the whole sorted list blends in one draw.
/// Two-sided (no culling), because a camera-facing disc has no meaningful back.
