/// What differs between the sprite, particle and text twins that draw into the transparent layer.
struct LayerDraw<'a> {
    vertex_entry: &'static str,
    /// The vertex buffer layout, `None` for a draw that decodes its quads from the instance index.
    buffer: Option<wgpu::VertexBufferLayout<'a>>,
    /// The kind's own depth compare, so the layer is covered exactly where the colour was.
    depth_compare: wgpu::CompareFunction,
}

/// The twin of a transparent kind's pipeline that writes the transparent layer: the same module and
/// layout, entry `fs_depth`, premultiplied blending. `Rg16Float` writes red and green; `Rgba16Float`
/// (the layer that carries the weighted medium) adds blue and leaves alpha alone.
fn build_layer_pipeline(
    device: &wgpu::Device,
    label: &str,
    src: &str,
    layout: &wgpu::PipelineLayout,
    draw: LayerDraw<'_>,
    format: wgpu::TextureFormat,
) -> wgpu::RenderPipeline {
    let shader = module(device, label, src);
    device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
        label: Some(label),
        layout: Some(layout),
        vertex: wgpu::VertexState {
            module: &shader,
            entry_point: Some(draw.vertex_entry),
            buffers: &draw.buffer.map(Some).into_iter().collect::<Vec<_>>(),
            compilation_options: wgpu::PipelineCompilationOptions::default(),
        },
        fragment: Some(wgpu::FragmentState {
            module: &shader,
            entry_point: Some("fs_depth"),
            targets: &[Some(wgpu::ColorTargetState {
                format,
                blend: Some(premultiplied_blend()),
                write_mask: if format == wgpu::TextureFormat::Rgba16Float {
                    wgpu::ColorWrites::RED | wgpu::ColorWrites::GREEN | wgpu::ColorWrites::BLUE
                } else {
                    wgpu::ColorWrites::RED | wgpu::ColorWrites::GREEN
                },
            })],
            compilation_options: wgpu::PipelineCompilationOptions::default(),
        }),
        primitive: wgpu::PrimitiveState::default(),
        depth_stencil: Some(depth_state(false, draw.depth_compare)),
        multisample: wgpu::MultisampleState::default(),
        multiview_mask: None,
        cache: None,
    })
}

